			t.Parallel()

			{
				encoded, err := EncodeJSON(&Function{})
				assert.NoError(t, err, "every kind encodes")
				assert.Contains(t, string(encoded), `"kind":"Function"`,
					"carrying its kind so a decoder can place it")
			}

